module case_range_1(input logic clk, rst, en, output logic [3:0] value);
  always_ff @(posedge clk or posedge rst) begin
    case (rst)
      1'b1: value <= 0;
      1'b0: begin
        case (value) inside
          [0:3]: begin
            case (en)
              1'b1: value <= value + 1;
              1'b0: value <= value;
            endcase
          end
          [4:7]: begin
            case (en)
              1'b1: value <= value - 1;
              1'b0: value <= value;
            endcase
          end
          [8:11]: value <= 4'b0101;
          [12:15]: value <= 0;
        endcase
      end
    endcase
  end
endmodule,"module case_range_1_assertions(input logic clk, rst, en, output logic [3:0] value)

module mem_ctrl (
    input logic clk,
    input logic [1:0] cmd,
    input logic [1:0] burst,
    output logic ack,
    output logic err
);
    always_ff @(posedge clk) begin
        ack <= 0;
        err <= 0;
        case (cmd)
            2'b00: begin // READ
                case (burst)
                    2'b00, 2'b01: ack <= 1;
                    default: err <= 1;
                endcase
            end

            2'b01: begin // WRITE
                case (burst)
                    2'b00, 2'b10: ack <= 1;
                    default: err <= 1;
                endcase
            end

            default: err <= 1;
        endcase
    end
endmodule,"module mem_ctrl_assertions (

