            1'b0: case(coeff) inside
                      {4'b0001, 4'b0010, 4'b0100, 4'b1000}:
                          case(update)
                              1'b1: coeff <= {coeff[2:0], coeff[3]};
                              1'b0: coeff <= coeff;
                              default: coeff <= coeff;
                          endcase
                      4'b0011: coeff <= 4'b0110;
                      4'b0110: coeff <= 4'b1100;
                      4'b1100: coeff <= 4'b1001;
                      4'b1001: coeff <= 4'b0011;
                      default: coeff <= 4'b0001;
                  endcase
