        case(rst)
            1'b1: pulse_pos <= 4'b0001;
            1'b0: case(pulse_pos)
                      4'b0000: pulse_pos <= 4'b0001;
                      4'b0001: case(shift_right)
                                   1'b1: pulse_pos <= 4'b0010;
                                   1'b0: case(shift_left)
                                             1'b1: pulse_pos <= 4'b1000;
                                             1'b0: pulse_pos <= pulse_pos;
                                             default: pulse_pos <= pulse_pos;
                                         endcase
                                   default: pulse_pos <= pulse_pos;
                               endcase
                      4'b0010: case(shift_right)
                                   1'b1: pulse_pos <= 4'b0100;
                                   1'b0: case(shift_left)
                                             1'b1: pulse_pos <= 4'b0001;
                                             1'b0: pulse_pos <= pulse_pos;
                                             default: pulse_pos <= pulse_pos;
                                         endcase
                                   default: pulse_pos <= pulse_pos;
                               endcase
                      4'b0100: case(shift_right)
                                   1'b1: pulse_pos <= 4'b1000;
                                   1'b0: case(shift_left)
                                             1'b1: pulse_pos <= 4'b0010;
                                             1'b0: pulse_pos <= pulse_pos;
                                             default: pulse_pos <= pulse_pos;
                                         endcase
                                   default: pulse_pos <= pulse_pos;
                               endcase
                      4'b1000: case(shift_right)
                                   1'b1: pulse_pos <= 4'b0001;
                                   1'b0: case(shift_left)
                                             1'b1: pulse_pos <= 4'b0100;
                                             1'b0: pulse_pos <= pulse_pos;
                                             default: pulse_pos <= pulse_pos;
                                         endcase
                                   default: pulse_pos <= pulse_pos;
                               endcase
                      default: pulse_pos <= 4'b0001;
