// Power Management Controller (PMC)
// Implements: State machine, Clock gating, Voltage scaling, Interrupt handling
// Protocol: Simple power management with sleep, deep-sleep, active, and performance modes
// Constraints: No if/else, no loops, only case statements

module pmc (
    input  logic        clk,           // System clock
    input  logic        rst_n,         // Active-low asynchronous reset
    input  logic        wake_req,      // Wake request from peripheral
    input  logic [1:0]  perf_req,      // Performance level request: 0=low, 1=medium, 2=high, 3=ultra
    input  logic [2:0]  sleep_timeout, // Timeout cycles for sleep entry
    input  logic [1:0]  ext_status,    // External power status (e.g., PMIC ready)

    output logic        clk_cpu_en,    // CPU clock enable
    output logic        clk_periph_en, // Peripheral clock enable
    output logic [1:0]  vdd_level,     // Voltage scaling: 0=0.8V, 1=1.0V, 2=1.2V, 3=1.35V
    output logic        sleep_ack,     // Acknowledge sleep entry
    output logic        wake_ack,      // Acknowledge wakeup
    output logic [1:0]  pmc_status,    // Status output: 0=active, 1=sleep, 2=deep-sleep, 3=performance
    output logic        power_good     // Indicates power rails stable
);

    // State encoding
    typedef enum logic [1:0] {
        ACTIVE      = 2'b00,
        SLEEP       = 2'b01,
        DEEP_SLEEP  = 2'b10,
        PERFORMANCE = 2'b11
    } state_t;

    state_t current_state, next_state;

    // Counters and registers
    logic [2:0]  sleep_cnt;       // Sleep entry counter
    logic [1:0]  vdd_req;         // Requested voltage level
    logic        wake_pending;     // Wake request pending
    logic        clk_switching;    // Clock switching in progress
    logic [1:0]  perf_level;       // Current performance level

    // -----------------------------------------------------------------
    // Block 1: Synchronous State Register (Sequential)
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= ACTIVE;
            1'b1: current_state <= next_state;
            default: current_state <= ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 2: Next State Logic (Combinational)
    // Uses nested case statements for state transitions
    // -----------------------------------------------------------------
    always_comb begin
        next_state = current_state;  // Default to stay in current state

        case (current_state)
            ACTIVE: begin
                case (wake_pending)
                    1'b0: begin
                        case (sleep_timeout)
                            3'b000: next_state = SLEEP;      // Timeout expired
                            default: next_state = ACTIVE;     // No timeout, stay active
                        endcase
                    end
                    1'b1: next_state = ACTIVE;  // Wake pending during active
                endcase

                // Performance mode request override
                case (perf_req)
                    2'b11: next_state = PERFORMANCE;
                    default: ;  // Keep previously computed state
                endcase
            end

            SLEEP: begin
                case ({wake_req, wake_pending})
                    2'b00: begin
                        case (sleep_timeout[2])  // Extended sleep check
                            1'b1: next_state = DEEP_SLEEP;
                            default: next_state = SLEEP;
                        endcase
                    end
                    default: next_state = ACTIVE;  // Wake requested
                endcase
            end

            DEEP_SLEEP: begin
                case (wake_req)
                    1'b1: next_state = ACTIVE;
                    default: next_state = DEEP_SLEEP;
                endcase
            end

            PERFORMANCE: begin
                case (perf_req)
                    2'b00: next_state = ACTIVE;
                    2'b01, 2'b10, 2'b11: next_state = PERFORMANCE;
                    default: next_state = ACTIVE;
                endcase
            end

            default: next_state = ACTIVE;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 3: Output and Control Logic (Combinational)
    // Generates all output signals based on current state and inputs
    // -----------------------------------------------------------------
    always_comb begin
        // Default values to avoid latches
        clk_cpu_en     = 1'b0;
        clk_periph_en  = 1'b0;
        vdd_level      = 2'b00;
        sleep_ack      = 1'b0;
        wake_ack       = 1'b0;
        pmc_status     = 2'b00;
        power_good     = 1'b0;
        vdd_req        = 2'b00;

        case (current_state)
            ACTIVE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                vdd_req       = 2'b01;  // 1.0V
                pmc_status    = 2'b00;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;

                case (ext_status)
                    2'b11: power_good = 1'b1;  // External PMIC ready
                    default: power_good = 1'b0;
                endcase

                // Voltage adjustment based on performance request
                case (perf_req)
                    2'b11: vdd_req = 2'b11;  // 1.35V for ultra
                    2'b10: vdd_req = 2'b10;  // 1.2V for high
                    default: vdd_req = 2'b01; // 1.0V for normal
                endcase
            end

            SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b1;   // Keep peripherals awake for wake detection
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b01;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;

                case (ext_status[1])
                    1'b1: power_good = 1'b1;
                    default: power_good = 1'b0;
                endcase
            end

            DEEP_SLEEP: begin
                clk_cpu_en    = 1'b0;
                clk_periph_en = 1'b0;
                vdd_req       = 2'b00;  // 0.8V
                pmc_status    = 2'b10;
                sleep_ack     = 1'b1;
                wake_ack      = 1'b0;
                power_good    = 1'b1;   // Power maintained in deep sleep
            end

            PERFORMANCE: begin
                clk_cpu_en    = 1'b1;
                clk_periph_en = 1'b1;
                pmc_status    = 2'b11;
                sleep_ack     = 1'b0;
                wake_ack      = 1'b0;
                power_good    = 1'b1;

                case (perf_level)
                    2'b11: vdd_req = 2'b11;  // Ultra: 1.35V
                    2'b10: vdd_req = 2'b10;  // High: 1.2V
                    2'b01: vdd_req = 2'b01;  // Medium: 1.0V
                    default: vdd_req = 2'b00; // Low: 0.8V
                endcase
            end

            default: ;
        endcase

        // Final voltage assignment (simulate PMIC settling time)
        case (clk_switching)
            1'b1: vdd_level = vdd_req;  // Apply new voltage after switching
            default: vdd_level = 2'b00;
        endcase
    end

    // -----------------------------------------------------------------
    // Block 4: Auxiliary Sequential Logic (Wake/Performance Management)
    // Handles wake pending and performance level tracking
    // -----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        // Reset handling using case on rst_n
        case (rst_n)
            1'b0: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
            1'b1: begin
                // Wake pending management
                case ({wake_req, wake_ack})
                    2'b10: wake_pending <= 1'b1;
                    2'b01: wake_pending <= 1'b0;
                    default: wake_pending <= wake_pending;
                endcase

                // Clock switching flag
                case (current_state)
                    ACTIVE: begin
                        case (perf_req)
                            2'b11: clk_switching <= 1'b1;
                            default: clk_switching <= 1'b0;
                        endcase
                    end
                    default: clk_switching <= 1'b0;
                endcase

                // Performance level tracking
                case (current_state)
                    PERFORMANCE: begin
                        case (perf_req)
                            2'b00: perf_level <= 2'b00;
                            2'b01: perf_level <= 2'b01;
                            2'b10: perf_level <= 2'b10;
                            2'b11: perf_level <= 2'b11;
                            default: perf_level <= perf_level;
                        endcase
                    end
                    default: perf_level <= 2'b00;
                endcase

                // Sleep counter (increment in sleep states)
                case (current_state)
                    SLEEP: begin
                        case (sleep_cnt)
                            3'b111: sleep_cnt <= 3'b111;
                            default: sleep_cnt <= sleep_cnt + 1'b1;
                        endcase
                    end
                    default: sleep_cnt <= 3'b000;
                endcase
            end
            default: begin
                wake_pending <= 1'b0;
                clk_switching <= 1'b0;
                perf_level <= 2'b00;
                sleep_cnt <= 3'b000;
            end
        endcase
    end

endmodule,"module pmc_assertions (

module debouncer_mealy (
    input logic clk,
    input logic rst_n,
    input logic noisy_in,
    input logic [15:0] debounce_time,
    output logic debounced_out
);

typedef enum logic [1:0] {STABLE0, COUNT0, STABLE1, COUNT1} state_t;
state_t state, next_state;
logic [15:0] counter, next_counter;

// Sequential logic
always_ff @(posedge clk or negedge rst_n) begin
    case (rst_n)
        1'b0: begin
            state <= STABLE0;
            counter <= 16'b0;
        end
        1'b1: begin
            state <= next_state;
            counter <= next_counter;
        end
    endcase
end

// Combinational logic
always_comb begin
    // Default assignments
    next_state = state;
    next_counter = counter;
    debounced_out = 1'b0;

    // Counter update logic
    case (state == COUNT0 || state == COUNT1)
        1'b1: next_counter = counter + 1;
        1'b0: next_counter = 16'b0;
    endcase

    case (state)
        STABLE0: begin
            debounced_out = 1'b0;
            case (noisy_in)
                1'b1: next_state = COUNT0;
            endcase
        end

        COUNT0: begin
            debounced_out = 1'b0;

            case (!noisy_in)
                1'b1: next_state = STABLE0;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE1;
                    debounced_out = 1'b1;  // Mealy: output high immediately
                end
            endcase
        end

        STABLE1: begin
            debounced_out = 1'b1;
            case (!noisy_in)
                1'b1: next_state = COUNT1;
            endcase
        end

        COUNT1: begin
            debounced_out = 1'b1;

            case (noisy_in)
                1'b1: next_state = STABLE1;  // Glitch, go back
            endcase

            case (counter == (debounce_time - 1))
                1'b1: begin
                    next_state = STABLE0;
                    debounced_out = 1'b0;  // Mealy: output low immediately
                end
            endcase
        end
    endcase
end

endmodule,"module debouncer_mealy_assertions (

module crc32_engine (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        data_valid,
    input  logic [31:0] data_in,
    input  logic        crc_init,
    output logic [31:0] crc_out,
    output logic        crc_valid
);

    // Polynomial: 0x04C11DB7 (Ethernet/PCIe)
    localparam CRC_POLY = 32'h04C11DB7;

    // Block 1: CRC Register (Case-only Sequential)
    logic [31:0] crc_reg;
    logic [31:0] crc_next;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: crc_reg <= 32'hFFFFFFFF;
            1'b1: begin
                case ({crc_init, data_valid})
                    2'b10, 2'b11: crc_reg <= 32'hFFFFFFFF;  // Init takes priority
                    2'b01:        crc_reg <= crc_next;
                    default:      crc_reg <= crc_reg;
                endcase
            end
        endcase
    end

    // Block 2: Parallel CRC Computation (Combinational)
    always_comb begin
        logic [31:0] data_xor;
        data_xor = data_in ^ crc_reg;

        // Parallel CRC calculation using case for each bit
        // Bit 0
        case (1'b1)
            1'b1: crc_next[0] = data_xor[31] ^ data_xor[29] ^ data_xor[28] ^ data_xor[26] ^
                                 data_xor[25] ^ data_xor[22] ^ data_xor[21] ^ data_xor[20] ^
                                 data_xor[19] ^ data_xor[18] ^ data_xor[17] ^ data_xor[16] ^
                                 data_xor[14] ^ data_xor[13] ^ data_xor[12] ^ data_xor[11] ^
                                 data_xor[9]  ^ data_xor[8]  ^ data_xor[7]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[0];
        endcase

        // Bit 1
        case (1'b1)
            1'b1: crc_next[1] = data_xor[30] ^ data_xor[28] ^ data_xor[27] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[21] ^ data_xor[20] ^ data_xor[19] ^
                                 data_xor[18] ^ data_xor[17] ^ data_xor[16] ^ data_xor[15] ^
                                 data_xor[13] ^ data_xor[12] ^ data_xor[11] ^ data_xor[10] ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[4]  ^
                                 data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase

        // Bit 31
        case (1'b1)
            1'b1: crc_next[31] = data_xor[28] ^ data_xor[27] ^ data_xor[26] ^ data_xor[25] ^
                                 data_xor[24] ^ data_xor[23] ^ data_xor[22] ^ data_xor[21] ^
                                 data_xor[20] ^ data_xor[19] ^ data_xor[18] ^ data_xor[17] ^
                                 data_xor[16] ^ data_xor[15] ^ data_xor[14] ^ data_xor[13] ^
                                 data_xor[12] ^ data_xor[11] ^ data_xor[10] ^ data_xor[9]  ^
                                 data_xor[8]  ^ data_xor[7]  ^ data_xor[6]  ^ data_xor[5]  ^
                                 data_xor[4]  ^ data_xor[3]  ^ data_xor[2]  ^ data_xor[1];
        endcase
    end

    // Block 3: Output Control (Case-only Combinational)
    always_comb begin
        case (data_valid)
            1'b1: begin
                crc_out = ~crc_reg;
                crc_valid = 1'b1;
            end
            default: begin
                crc_out = 32'b0;
                crc_valid = 1'b0;
            end
        endcase
    end

    // Block 4: Error Detection (Case-only Combinational)
    logic [31:0] expected_crc;
    logic crc_error;

    always_comb begin
        expected_crc = 32'hDEBB20E3;
        case (crc_out != expected_crc && crc_valid)
            1'b1: crc_error = 1'b1;
            default: crc_error = 1'b0;
        endcase
    end

endmodule,"module crc32_engine_assertions (

// DDR3 Memory Controller Command Scheduler
// Uses ONLY case statements - no if/else, no loops
// Manages command priority, bank state machine, and timing constraints

module ddr3_cmd_scheduler (
    input  logic        clk,
    input  logic        rst_n,

    // Command interface from controller
    input  logic [2:0]  cmd_type,      // 0:ACT, 1:RD, 2:WR, 3:PRE, 4:REF, 5:ZQ
    input  logic [2:0]  bank_addr,
    input  logic [14:0] row_addr,
    input  logic        cmd_valid,
    output logic        cmd_ready,

    // Command output to PHY
    output logic [2:0]  phy_cmd_type,
    output logic [2:0]  phy_bank_addr,
    output logic [14:0] phy_row_addr,
    output logic        phy_cmd_valid,
    input  logic        phy_cmd_accept,

    // Bank status
    input  logic [7:0]  bank_active_row [7:0],  // Current open row per bank
    input  logic [7:0]  bank_state      [7:0],  // 0:idle, 1:active, 2:precharging
    input  logic [7:0]  bank_timer      [7:0]   // Timing constraint counters
);

    //=========================================================================
    // Local parameters
    //=========================================================================
    localparam CMD_ACT = 3'd0;
    localparam CMD_RD  = 3'd1;
    localparam CMD_WR  = 3'd2;
    localparam CMD_PRE = 3'd3;
    localparam CMD_REF = 3'd4;
    localparam CMD_ZQ  = 3'd5;

    localparam BANK_IDLE       = 3'd0;
    localparam BANK_ACTIVE     = 3'd1;
    localparam BANK_PRECHARGING = 3'd2;

    localparam SCHED_IDLE      = 2'd0;
    localparam SCHED_CHECK     = 2'd1;
    localparam SCHED_ISSUE     = 2'd2;
    localparam SCHED_WAIT      = 2'd3;

    //=========================================================================
    // Internal signals
    //=========================================================================
    logic [1:0]  sched_state;
    logic [2:0]  selected_bank;
    logic [2:0]  pending_cmd_type;
    logic [2:0]  pending_bank;
    logic [14:0] pending_row;
    logic        pending_valid;

    logic [2:0]  arbitration_result;
    logic        bank_match;
    logic        row_match;
    logic        bank_ready;
    logic [7:0]  bank_active_row_local;
    logic [7:0]  bank_state_local;
    logic [7:0]  bank_timer_local;

    //=========================================================================
    // Block 1: Combinational - Command Arbitration
    // Selects highest priority command from pending queue
    // Uses case statement for priority encoding
    //=========================================================================
    always_comb begin
        // Default values
        arbitration_result = 3'd0;

        // Priority encoder using nested case statements
        // Priority: REF > ZQ > ACT > PRE > WR > RD
        case (cmd_valid)
            1'b1: begin
                case (cmd_type)
                    CMD_REF: arbitration_result = CMD_REF;
                    CMD_ZQ:  arbitration_result = CMD_ZQ;
                    CMD_ACT: arbitration_result = CMD_ACT;
                    CMD_PRE: arbitration_result = CMD_PRE;
                    CMD_WR:  arbitration_result = CMD_WR;
                    CMD_RD:  arbitration_result = CMD_RD;
                    default: arbitration_result = CMD_RD;
                endcase
            end
            default: arbitration_result = 3'b111;  // No command
        endcase
    end

    //=========================================================================
    // Block 2: Combinational - Bank Status Evaluation
    // Determines if selected bank can accept the command
    // Uses case statements for bank state and timing checks
    //=========================================================================
    always_comb begin
        // Extract bank-specific signals
        case (pending_bank)
            3'd0: begin
                bank_active_row_local = bank_active_row[0];
                bank_state_local = bank_state[0];
                bank_timer_local = bank_timer[0];
            end
            3'd1: begin
                bank_active_row_local = bank_active_row[1];
                bank_state_local = bank_state[1];
                bank_timer_local = bank_timer[1];
            end
            3'd2: begin
                bank_active_row_local = bank_active_row[2];
                bank_state_local = bank_state[2];
                bank_timer_local = bank_timer[2];
            end
            3'd3: begin
                bank_active_row_local = bank_active_row[3];
                bank_state_local = bank_state[3];
                bank_timer_local = bank_timer[3];
            end
            3'd4: begin
                bank_active_row_local = bank_active_row[4];
                bank_state_local = bank_state[4];
                bank_timer_local = bank_timer[4];
            end
            3'd5: begin
                bank_active_row_local = bank_active_row[5];
                bank_state_local = bank_state[5];
                bank_timer_local = bank_timer[5];
            end
            3'd6: begin
                bank_active_row_local = bank_active_row[6];
                bank_state_local = bank_state[6];
                bank_timer_local = bank_timer[6];
            end
            default: begin
                bank_active_row_local = bank_active_row[7];
                bank_state_local = bank_state[7];
                bank_timer_local = bank_timer[7];
            end
        endcase

        // Check if row matches open row
        row_match = (bank_active_row_local == pending_row);

        // Check if bank is ready based on state and timer
        case (bank_state_local)
            BANK_IDLE: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRRD check
                    CMD_REF: bank_ready = (bank_timer_local == 8'd0);  // tRC check
                    default: bank_ready = 1'b0;  // Can't do RD/WR on idle bank
                endcase
            end
            BANK_ACTIVE: begin
                case (pending_cmd_type)
                    CMD_RD, CMD_WR: begin
                        case (row_match)
                            1'b1: bank_ready = (bank_timer_local == 8'd0);  // tRCD satisfied
                            1'b0: bank_ready = 1'b0;  // Need PRE first
                        endcase
                    end
                    CMD_PRE: bank_ready = (bank_timer_local == 8'd0);  // tRAS satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            BANK_PRECHARGING: begin
                case (pending_cmd_type)
                    CMD_ACT: bank_ready = (bank_timer_local == 8'd0);  // tRP satisfied
                    default: bank_ready = 1'b0;
                endcase
            end
            default: bank_ready = 1'b0;
        endcase
    end

    //=========================================================================
    // Block 3: Sequential - Command Pending Register
    // Latches incoming command when accepted
    // Uses case for state-based latching
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                pending_cmd_type <= 3'd0;
                pending_bank     <= 3'd0;
                pending_row      <= 15'd0;
                pending_valid    <= 1'b0;
                cmd_ready        <= 1'b1;
            end
            1'b1: begin
                case (sched_state)
                    SCHED_IDLE: begin
                        // Accept new command when scheduler idle
                        case (cmd_valid)
                            1'b1: begin
                                pending_cmd_type <= arbitration_result;
                                pending_bank     <= bank_addr;
                                pending_row      <= row_addr;
                                pending_valid    <= 1'b1;
                                cmd_ready        <= 1'b0;
                            end
                            default: begin
                                pending_valid    <= 1'b0;
                                cmd_ready        <= 1'b1;
                                // Preserve existing values for other registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                        endcase
                    end
                    SCHED_ISSUE: begin
                        // Command issued, clear pending
                        case (phy_cmd_accept)
                            1'b1: begin
                                pending_valid <= 1'b0;
                                cmd_ready     <= 1'b1;
                                // Preserve existing values for other registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                            default: begin
                                pending_valid <= pending_valid;
                                cmd_ready     <= 1'b0;
                                // Preserve existing values for all registers
                                pending_cmd_type <= pending_cmd_type;
                                pending_bank     <= pending_bank;
                                pending_row      <= pending_row;
                            end
                        endcase
                    end
                    default: begin
                        // Keep pending during check/wait states
                        pending_valid <= pending_valid;
                        cmd_ready     <= 1'b0;
                        // Preserve existing values for all registers
                        pending_cmd_type <= pending_cmd_type;
                        pending_bank     <= pending_bank;
                        pending_row      <= pending_row;
                    end
                endcase
            end
        endcase
    end

    //=========================================================================
    // Block 4: Sequential - Scheduler FSM
    // Manages command issuance flow using case statements
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                sched_state   <= SCHED_IDLE;
                phy_cmd_type  <= 3'd0;
                phy_bank_addr <= 3'd0;
                phy_row_addr  <= 15'd0;
                phy_cmd_valid <= 1'b0;
            end
            1'b1: begin
                case (sched_state)
                    SCHED_IDLE: begin
                        phy_cmd_valid <= 1'b0;
                        case (pending_valid)
                            1'b1: sched_state <= SCHED_CHECK;
                            default: sched_state <= SCHED_IDLE;
                        endcase
                    end

                    SCHED_CHECK: begin
                        phy_cmd_valid <= 1'b0;
                        // Evaluate if command can be issued based on bank status
                        case (bank_ready)
                            1'b1: sched_state <= SCHED_ISSUE;
                            1'b0: begin
                                // Need to insert auto-precharge if row mismatch
                                case ({pending_cmd_type, bank_state_local, row_match})
                                    {CMD_RD, BANK_ACTIVE, 1'b0},
                                    {CMD_WR, BANK_ACTIVE, 1'b0}: begin
                                        // Auto-generate precharge command
                                        phy_cmd_type  <= CMD_PRE;
                                        phy_bank_addr <= pending_bank;
                                        phy_row_addr  <= 15'd0;
                                        phy_cmd_valid <= 1'b1;
                                        sched_state   <= SCHED_WAIT;
                                    end
                                    default: begin
                                        sched_state <= SCHED_WAIT;
                                    end
                                endcase
                            end
                        endcase
                    end

                    SCHED_ISSUE: begin
                        // Issue the pending command
                        case (pending_valid)
                            1'b1: begin
                                phy_cmd_type  <= pending_cmd_type;
                                phy_bank_addr <= pending_bank;
                                phy_row_addr  <= pending_row;
                                phy_cmd_valid <= 1'b1;

                                case (phy_cmd_accept)
                                    1'b1: sched_state <= SCHED_IDLE;
                                    default: sched_state <= SCHED_ISSUE;
                                endcase
                            end
                            default: begin
                                sched_state <= SCHED_IDLE;
                            end
                        endcase
                    end

                    SCHED_WAIT: begin
                        // Wait for timing constraints
                        case (phy_cmd_accept)
                            1'b1: begin
                                phy_cmd_valid <= 1'b0;
                                sched_state   <= SCHED_IDLE;
                            end
                            default: begin
                                phy_cmd_valid <= phy_cmd_valid;
                                sched_state   <= SCHED_WAIT;
                            end
                        endcase
                    end

                    default: begin
                        sched_state <= SCHED_IDLE;
                    end
                endcase
            end
        endcase
    end

endmodule,"module ddr3_cmd_scheduler_assertions (

module pcie_tlp_decoder (
    input  logic        clk,
    input  logic        rst_n,

    // TLP Input Stream
    input  logic        tlp_valid,
    input  logic [63:0] tlp_data,      // 64-bit TLP data
    input  logic        tlp_start,      // Start of TLP
    input  logic        tlp_end,        // End of TLP
    input  logic [2:0]  tlp_dw_count,   // Double-word count (1-4 DWs for header)

    // Decoded TLP Header Fields
    output logic [7:0]  tlp_fmt_type,   // Format and Type (bits 0-7)
    output logic [9:0]  tlp_length,     // Payload length in DWs
    output logic [15:0] tlp_requester_id, // Requester ID (Bus:Device:Function)
    output logic [15:0] tlp_completer_id, // Completer ID
    output logic [7:0]  tlp_tag,        // Transaction Tag
    output logic [31:0] tlp_address,    // Address for memory transactions
    output logic [31:0] tlp_data_payload, // First 4 bytes of data payload
    output logic [3:0]  tlp_first_be,   // First DW Byte Enables
    output logic [3:0]  tlp_last_be,    // Last DW Byte Enables

    // Transaction Type Flags
    output logic        tlp_mem_read,
    output logic        tlp_mem_write,
    output logic        tlp_cfg_read,
    output logic        tlp_cfg_write,
    output logic        tlp_completion,
    output logic        tlp_completion_data,

    // Error Detection
    output logic        tlp_parity_error,
    output logic        tlp_format_error,
    output logic        tlp_decode_done
);

    // Block 1: TLP State Machine (Sequential)
    typedef enum logic [2:0] {
        IDLE          = 3'b000,
        HEADER_DW0    = 3'b001,
        HEADER_DW1    = 3'b010,
        HEADER_DW2    = 3'b011,
        HEADER_DW3    = 3'b100,
        DATA_PAYLOAD  = 3'b101,
        DECODE_DONE   = 3'b110,
        ERROR         = 3'b111
    } tlp_state_t;

    tlp_state_t current_state, next_state;

    // Header storage registers
    logic [31:0] header_dw0;
    logic [31:0] header_dw1;
    logic [31:0] header_dw2;
    logic [31:0] header_dw3;
    logic [31:0] payload_data;

    // Decoded fields
    logic [7:0]  decoded_fmt_type;
    logic [9:0]  decoded_length;
    logic [15:0] decoded_requester_id;
    logic [15:0] decoded_completer_id;
    logic [7:0]  decoded_tag;
    logic [31:0] decoded_address;
    logic [3:0]  decoded_first_be;
    logic [3:0]  decoded_last_be;
    logic [31:0] decoded_payload;

    // Control signals
    logic [1:0]  header_dw_counter;
    logic        is_3dw_header;
    logic        is_4dw_header;
    logic        has_payload;
    logic [9:0]  payload_dw_remaining;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    // Block 2: Header Counter and Payload Tracker (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw_counter <= 2'b0;
                payload_dw_remaining <= 10'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (tlp_start)
                            1'b1: begin
                                header_dw_counter <= 2'b0;
                                payload_dw_remaining <= 10'b0;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    HEADER_DW0, HEADER_DW1, HEADER_DW2, HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter + 2'd1;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining - 10'd2;  // 2 DWs per cycle
                            end
                            default: begin
                                header_dw_counter <= header_dw_counter;
                                payload_dw_remaining <= payload_dw_remaining;
                            end
                        endcase
                    end

                    default: begin
                        header_dw_counter <= header_dw_counter;
                        payload_dw_remaining <= payload_dw_remaining;
                    end
                endcase
            end
        endcase
    end

    // Block 3: Header Type Detection (Combinational)
    always_comb begin
        is_3dw_header = 1'b0;
        is_4dw_header = 1'b0;
        has_payload = 1'b0;

        case (header_dw0[30:24])  // Fmt[2:0] and Type[4:0] bits
            8'b000_00000: begin  // MRd - Memory Read (3DW header)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b001_00000: begin  // MRdLk - Memory Read Locked (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_00000: begin  // MWr - Memory Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b100_00100: begin  // CfgRd0 - Configuration Read (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b101_00100: begin  // CfgWr0 - Configuration Write (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_01010: begin  // Cpl - Completion without data (3DW)
                is_3dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b010_01011: begin  // CplD - Completion with data (3DW with payload)
                is_3dw_header = 1'b1;
                has_payload = 1'b1;
            end
            8'b010_00001: begin  // MRd64 - Memory Read 64-bit (4DW header)
                is_4dw_header = 1'b1;
                has_payload = 1'b0;
            end
            8'b011_00001: begin  // MWr64 - Memory Write 64-bit (4DW with payload)
                is_4dw_header = 1'b1;
                has_payload = 1'b1;
            end
            default: begin
                is_3dw_header = 1'b0;
                is_4dw_header = 1'b0;
                has_payload = 1'b0;
            end
        endcase
    end

    // Block 4: State Transition Logic (Case-only Combinational)
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (tlp_start)
                    1'b1: next_state = HEADER_DW0;
                    default: next_state = IDLE;
                endcase
            end

            HEADER_DW0: begin
                case (tlp_valid)
                    1'b1: next_state = HEADER_DW1;
                    default: next_state = HEADER_DW0;
                endcase
            end

            HEADER_DW1: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_3dw_header)
                            1'b1: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                            default: next_state = HEADER_DW2;
                        endcase
                    end
                    default: next_state = HEADER_DW1;
                endcase
            end

            HEADER_DW2: begin
                case (tlp_valid)
                    1'b1: begin
                        case (is_4dw_header)
                            1'b1: next_state = HEADER_DW3;
                            default: begin
                                case (has_payload)
                                    1'b1: next_state = DATA_PAYLOAD;
                                    default: next_state = DECODE_DONE;
                                endcase
                            end
                        endcase
                    end
                    default: next_state = HEADER_DW2;
                endcase
            end

            HEADER_DW3: begin
                case (tlp_valid)
                    1'b1: begin
                        case (has_payload)
                            1'b1: next_state = DATA_PAYLOAD;
                            default: next_state = DECODE_DONE;
                        endcase
                    end
                    default: next_state = HEADER_DW3;
                endcase
            end

            DATA_PAYLOAD: begin
                case ({tlp_end, (payload_dw_remaining <= 10'd2)})
                    2'b10, 2'b11: next_state = DECODE_DONE;
                    default: next_state = DATA_PAYLOAD;
                endcase
            end

            DECODE_DONE: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = DECODE_DONE;
                endcase
            end

            ERROR: begin
                case (tlp_end)
                    1'b1: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = ERROR;
        endcase
    end

    // Block 5: Header Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                header_dw0 <= 32'b0;
                header_dw1 <= 32'b0;
                header_dw2 <= 32'b0;
                header_dw3 <= 32'b0;
            end
            1'b1: begin
                case (current_state)
                    HEADER_DW0: begin
                        case (tlp_valid)
                            1'b1: header_dw0 <= tlp_data[63:32];  // First DW is upper 32 bits
                            default: header_dw0 <= header_dw0;
                        endcase
                    end

                    HEADER_DW1: begin
                        case (tlp_valid)
                            1'b1: header_dw1 <= tlp_data[31:0];   // Second DW is lower 32 bits
                            default: header_dw1 <= header_dw1;
                        endcase
                    end

                    HEADER_DW2: begin
                        case (tlp_valid)
                            1'b1: header_dw2 <= tlp_data[63:32];
                            default: header_dw2 <= header_dw2;
                        endcase
                    end

                    HEADER_DW3: begin
                        case (tlp_valid)
                            1'b1: header_dw3 <= tlp_data[31:0];
                            default: header_dw3 <= header_dw3;
                        endcase
                    end

                    default: begin
                        header_dw0 <= header_dw0;
                        header_dw1 <= header_dw1;
                        header_dw2 <= header_dw2;
                        header_dw3 <= header_dw3;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Payload Data Capture (Sequential)
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: payload_data <= 32'b0;
            1'b1: begin
                case (current_state)
                    DATA_PAYLOAD: begin
                        case (tlp_valid)
                            1'b1: payload_data <= tlp_data[31:0];  // Capture first 4 bytes of payload
                            default: payload_data <= payload_data;
                        endcase
                    end
                    default: payload_data <= payload_data;
                endcase
            end
        endcase
    end

    // Block 7: Header Field Decoding (Combinational)
    always_comb begin
        decoded_fmt_type = 8'b0;
        decoded_length = 10'b0;
        decoded_requester_id = 16'b0;
        decoded_completer_id = 16'b0;
        decoded_tag = 8'b0;
        decoded_address = 32'b0;
        decoded_first_be = 4'b0;
        decoded_last_be = 4'b0;
        decoded_payload = 32'b0;

        case (current_state)
            DECODE_DONE: begin
                // Fmt and Type fields
                decoded_fmt_type = header_dw0[30:23];

                // Length field (in DWs)
                decoded_length = header_dw0[9:0];

                // Requester ID (Bus:Device:Function)
                decoded_requester_id = header_dw1[31:16];

                case (is_3dw_header)
                    1'b1: begin
                        // Tag field
                        decoded_tag = header_dw1[7:0];

                        // Address for 32-bit addressing
                        decoded_address = {header_dw2[31:2], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw1[15:12];
                        decoded_last_be = header_dw1[11:8];

                        // Completer ID for completions
                        case (header_dw0[24:20])  // Type field
                            5'b01010, 5'b01011: begin  // Cpl or CplD
                                decoded_completer_id = header_dw2[31:16];
                            end
                            default: decoded_completer_id = 16'b0;
                        endcase
                    end
                    default: begin  // 4DW header
                        // Tag field
                        decoded_tag = header_dw2[7:0];

                        // Address for 64-bit addressing
                        decoded_address = {header_dw2[31:2], header_dw3[31:0], 2'b0};

                        // First and Last DW Byte Enables
                        decoded_first_be = header_dw2[15:12];
                        decoded_last_be = header_dw2[11:8];
                    end
                endcase

                // Payload data
                decoded_payload = payload_data;
            end

            default: begin
                decoded_fmt_type = decoded_fmt_type;
                decoded_length = decoded_length;
                decoded_requester_id = decoded_requester_id;
                decoded_completer_id = decoded_completer_id;
                decoded_tag = decoded_tag;
                decoded_address = decoded_address;
                decoded_first_be = decoded_first_be;
                decoded_last_be = decoded_last_be;
                decoded_payload = decoded_payload;
            end
        endcase
    end

    // Block 8: Transaction Type Detection (Combinational)
    always_comb begin
        tlp_mem_read = 1'b0;
        tlp_mem_write = 1'b0;
        tlp_cfg_read = 1'b0;
        tlp_cfg_write = 1'b0;
        tlp_completion = 1'b0;
        tlp_completion_data = 1'b0;

        case (decoded_fmt_type)
            8'b000_00000, 8'b001_00000: tlp_mem_read = 1'b1;   // MRd, MRdLk
            8'b010_00000: tlp_mem_write = 1'b1;                // MWr
            8'b100_00100: tlp_cfg_read = 1'b1;                 // CfgRd0
            8'b101_00100: tlp_cfg_write = 1'b1;                // CfgWr0
            8'b010_01010: tlp_completion = 1'b1;               // Cpl
            8'b010_01011: begin                                // CplD
                tlp_completion = 1'b1;
                tlp_completion_data = 1'b1;
            end
            default: begin
                tlp_mem_read = 1'b0;
                tlp_mem_write = 1'b0;
                tlp_cfg_read = 1'b0;
                tlp_cfg_write = 1'b0;
                tlp_completion = 1'b0;
                tlp_completion_data = 1'b0;
            end
        endcase
    end

    // Block 9: Output Assignment and Error Detection (Combinational)
    always_comb begin
        tlp_fmt_type = decoded_fmt_type;
        tlp_length = decoded_length;
        tlp_requester_id = decoded_requester_id;
        tlp_completer_id = decoded_completer_id;
        tlp_tag = decoded_tag;
        tlp_address = decoded_address;
        tlp_data_payload = decoded_payload;
        tlp_first_be = decoded_first_be;
        tlp_last_be = decoded_last_be;
        tlp_decode_done = 1'b0;
        tlp_parity_error = 1'b0;
        tlp_format_error = 1'b0;

        case (current_state)
            DECODE_DONE: begin
                tlp_decode_done = 1'b1;

                // Format error detection
                case ({is_3dw_header, is_4dw_header, (tlp_dw_count >= 3'd3)})
                    3'b100: tlp_format_error = 1'b0;
                    3'b010: tlp_format_error = 1'b0;
                    default: tlp_format_error = 1'b1;
                endcase

                // Parity error detection (simplified - would check ECRC in real design)
                case (^header_dw0 ^ ^header_dw1 ^ ^header_dw2 ^ ^header_dw3)
                    1'b1: tlp_parity_error = 1'b1;
                    default: tlp_parity_error = 1'b0;
                endcase
            end

            ERROR: begin
                tlp_format_error = 1'b1;
                tlp_decode_done = 1'b1;
            end

            default: begin
                tlp_decode_done = 1'b0;
                tlp_parity_error = 1'b0;
                tlp_format_error = 1'b0;
            end
        endcase
    end

