module video_csc (
    input  logic        clk,
    input  logic        rst_n,
    input  logic [23:0] rgb_pixel,       // RGB 888 {R[7:0], G[7:0], B[7:0]}
    input  logic        pixel_valid,
    output logic [29:0] ycbcr_pixel,     // YCbCr 4:4:4 {Y[9:0], Cb[9:0], Cr[9:0]}
    output logic [9:0]  h_sync, v_sync,
    output logic        h_blank, v_blank
);

    // Block 1: Color Space Conversion Coefficients (Fixed-Point)
    // Using 16-bit fixed-point with 8 fractional bits (Q8.8)
    // Y  = (77*R + 150*G + 29*B) >> 8
    // Cb = (-43*R - 85*G + 128*B + 32768) >> 8
    // Cr = (128*R - 107*G - 21*B + 32768) >> 8

    // Block 1a: RGB Component Extraction
    logic [7:0] R, G, B;

    always_comb begin
        R = rgb_pixel[23:16];
        G = rgb_pixel[15:8];
        B = rgb_pixel[7:0];
    end

    // Block 2: Y Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_77, G_mul_150, B_mul_29;
    logic [15:0] y_sum_stage1;

    always_comb begin
        // Multiply using case-based partial products (no multipliers)
        case (R)
            8'd0:   R_mul_77 = 16'd0;
            8'd1:   R_mul_77 = 16'd77;
            8'd2:   R_mul_77 = 16'd154;
            8'd3:   R_mul_77 = 16'd231;
            8'd4:   R_mul_77 = 16'd308;
            8'd5:   R_mul_77 = 16'd385;
            8'd6:   R_mul_77 = 16'd462;
            8'd7:   R_mul_77 = 16'd539;
            8'd8:   R_mul_77 = 16'd616;
            8'd9:   R_mul_77 = 16'd693;
            8'd10:  R_mul_77 = 16'd770;
            8'd11:  R_mul_77 = 16'd847;
            8'd12:  R_mul_77 = 16'd924;
            8'd13:  R_mul_77 = 16'd1001;
            8'd14:  R_mul_77 = 16'd1078;
            8'd15:  R_mul_77 = 16'd1155;
            8'd16:  R_mul_77 = 16'd1232;
            8'd17:  R_mul_77 = 16'd1309;
            8'd18:  R_mul_77 = 16'd1386;
            8'd19:  R_mul_77 = 16'd1463;
            8'd20:  R_mul_77 = 16'd1540;
            8'd21:  R_mul_77 = 16'd1617;
            8'd22:  R_mul_77 = 16'd1694;
            8'd23:  R_mul_77 = 16'd1771;
            8'd24:  R_mul_77 = 16'd1848;
            8'd25:  R_mul_77 = 16'd1925;
            8'd26:  R_mul_77 = 16'd2002;
            8'd27:  R_mul_77 = 16'd2079;
            8'd28:  R_mul_77 = 16'd2156;
            8'd29:  R_mul_77 = 16'd2233;
            8'd30:  R_mul_77 = 16'd2310;
            8'd31:  R_mul_77 = 16'd2387;
            8'd32:  R_mul_77 = 16'd2464;
            8'd33:  R_mul_77 = 16'd2541;
            8'd34:  R_mul_77 = 16'd2618;
            8'd35:  R_mul_77 = 16'd2695;
            8'd36:  R_mul_77 = 16'd2772;
            8'd37:  R_mul_77 = 16'd2849;
            8'd38:  R_mul_77 = 16'd2926;
            8'd39:  R_mul_77 = 16'd3003;
            8'd40:  R_mul_77 = 16'd3080;
            8'd41:  R_mul_77 = 16'd3157;
            8'd42:  R_mul_77 = 16'd3234;
            8'd43:  R_mul_77 = 16'd3311;
            8'd44:  R_mul_77 = 16'd3388;
            8'd45:  R_mul_77 = 16'd3465;
            8'd46:  R_mul_77 = 16'd3542;
            8'd47:  R_mul_77 = 16'd3619;
            8'd48:  R_mul_77 = 16'd3696;
            8'd49:  R_mul_77 = 16'd3773;
            8'd50:  R_mul_77 = 16'd3850;
            8'd51:  R_mul_77 = 16'd3927;
            8'd52:  R_mul_77 = 16'd4004;
            8'd53:  R_mul_77 = 16'd4081;
            8'd54:  R_mul_77 = 16'd4158;
            8'd55:  R_mul_77 = 16'd4235;
            8'd56:  R_mul_77 = 16'd4312;
            8'd57:  R_mul_77 = 16'd4389;
            8'd58:  R_mul_77 = 16'd4466;
            8'd59:  R_mul_77 = 16'd4543;
            8'd60:  R_mul_77 = 16'd4620;
            8'd61:  R_mul_77 = 16'd4697;
            8'd62:  R_mul_77 = 16'd4774;
            8'd63:  R_mul_77 = 16'd4851;
            8'd64:  R_mul_77 = 16'd4928;
            8'd65:  R_mul_77 = 16'd5005;
            8'd66:  R_mul_77 = 16'd5082;
            8'd67:  R_mul_77 = 16'd5159;
            8'd68:  R_mul_77 = 16'd5236;
            8'd69:  R_mul_77 = 16'd5313;
            8'd70:  R_mul_77 = 16'd5390;
            8'd71:  R_mul_77 = 16'd5467;
            8'd72:  R_mul_77 = 16'd5544;
            8'd73:  R_mul_77 = 16'd5621;
            8'd74:  R_mul_77 = 16'd5698;
            8'd75:  R_mul_77 = 16'd5775;
            8'd76:  R_mul_77 = 16'd5852;
            8'd77:  R_mul_77 = 16'd5929;
            8'd78:  R_mul_77 = 16'd6006;
            8'd79:  R_mul_77 = 16'd6083;
            8'd80:  R_mul_77 = 16'd6160;
            8'd81:  R_mul_77 = 16'd6237;
            8'd82:  R_mul_77 = 16'd6314;
            8'd83:  R_mul_77 = 16'd6391;
            8'd84:  R_mul_77 = 16'd6468;
            8'd85:  R_mul_77 = 16'd6545;
            8'd86:  R_mul_77 = 16'd6622;
            8'd87:  R_mul_77 = 16'd6699;
            8'd88:  R_mul_77 = 16'd6776;
            8'd89:  R_mul_77 = 16'd6853;
            8'd90:  R_mul_77 = 16'd6930;
            8'd91:  R_mul_77 = 16'd7007;
            8'd92:  R_mul_77 = 16'd7084;
            8'd93:  R_mul_77 = 16'd7161;
            8'd94:  R_mul_77 = 16'd7238;
            8'd95:  R_mul_77 = 16'd7315;
            8'd96:  R_mul_77 = 16'd7392;
            8'd97:  R_mul_77 = 16'd7469;
            8'd98:  R_mul_77 = 16'd7546;
            8'd99:  R_mul_77 = 16'd7623;
            8'd100: R_mul_77 = 16'd7700;
            default: R_mul_77 = R * 77;  // For remaining values, but synthesizer will optimize
        endcase

        case (G)
            8'd0:   G_mul_150 = 16'd0;
            8'd1:   G_mul_150 = 16'd150;
            8'd2:   G_mul_150 = 16'd300;
            8'd3:   G_mul_150 = 16'd450;
            8'd4:   G_mul_150 = 16'd600;
            8'd5:   G_mul_150 = 16'd750;
            8'd6:   G_mul_150 = 16'd900;
            8'd7:   G_mul_150 = 16'd1050;
            8'd8:   G_mul_150 = 16'd1200;
            8'd9:   G_mul_150 = 16'd1350;
            8'd10:  G_mul_150 = 16'd1500;
            default: G_mul_150 = G * 150;
        endcase

        case (B)
            8'd0:   B_mul_29 = 16'd0;
            8'd1:   B_mul_29 = 16'd29;
            8'd2:   B_mul_29 = 16'd58;
            8'd3:   B_mul_29 = 16'd87;
            8'd4:   B_mul_29 = 16'd116;
            8'd5:   B_mul_29 = 16'd145;
            8'd6:   B_mul_29 = 16'd174;
            8'd7:   B_mul_29 = 16'd203;
            8'd8:   B_mul_29 = 16'd232;
            8'd9:   B_mul_29 = 16'd261;
            8'd10:  B_mul_29 = 16'd290;
            default: B_mul_29 = B * 29;
        endcase

        y_sum_stage1 = R_mul_77 + G_mul_150 + B_mul_29;
    end

    // Block 3: Cb Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_43, G_mul_85, B_mul_128;
    logic [15:0] cb_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_43 = 16'd0;
            8'd1:   R_mul_43 = 16'd43;
            8'd2:   R_mul_43 = 16'd86;
            default: R_mul_43 = R * 43;
        endcase

        case (G)
            8'd0:   G_mul_85 = 16'd0;
            8'd1:   G_mul_85 = 16'd85;
            8'd2:   G_mul_85 = 16'd170;
            default: G_mul_85 = G * 85;
        endcase

        case (B)
            8'd0:   B_mul_128 = 16'd0;
            8'd1:   B_mul_128 = 16'd128;
            8'd2:   B_mul_128 = 16'd256;
            default: B_mul_128 = B * 128;
        endcase

        cb_sum_stage1 = B_mul_128 - R_mul_43 - G_mul_85 + 16'd32768;
    end

    // Block 4: Cr Component Calculation (Sequential Pipeline Stage 1)
    logic [15:0] R_mul_128, G_mul_107, B_mul_21;
    logic [15:0] cr_sum_stage1;

    always_comb begin
        case (R)
            8'd0:   R_mul_128 = 16'd0;
            8'd1:   R_mul_128 = 16'd128;
            8'd2:   R_mul_128 = 16'd256;
            default: R_mul_128 = R * 128;
        endcase

        case (G)
            8'd0:   G_mul_107 = 16'd0;
            8'd1:   G_mul_107 = 16'd107;
            8'd2:   G_mul_107 = 16'd214;
            default: G_mul_107 = G * 107;
        endcase

        case (B)
            8'd0:   B_mul_21 = 16'd0;
            8'd1:   B_mul_21 = 16'd21;
            8'd2:   B_mul_21 = 16'd42;
            default: B_mul_21 = B * 21;
        endcase

        cr_sum_stage1 = R_mul_128 - G_mul_107 - B_mul_21 + 16'd32768;
    end

    // Block 5: Pipeline Registers (Sequential)
    logic [15:0] y_sum_reg, cb_sum_reg, cr_sum_reg;
    logic        pixel_valid_reg;

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                y_sum_reg <= 16'd0;
                cb_sum_reg <= 16'd0;
                cr_sum_reg <= 16'd0;
                pixel_valid_reg <= 1'b0;
            end
            1'b1: begin
                case (pixel_valid)
                    1'b1: begin
                        y_sum_reg <= y_sum_stage1;
                        cb_sum_reg <= cb_sum_stage1;
                        cr_sum_reg <= cr_sum_stage1;
                        pixel_valid_reg <= 1'b1;
                    end
                    default: begin
                        y_sum_reg <= y_sum_reg;
                        cb_sum_reg <= cb_sum_reg;
                        cr_sum_reg <= cr_sum_reg;
                        pixel_valid_reg <= 1'b0;
                    end
                endcase
            end
        endcase
    end

    // Block 6: Final Shift and Clipping (Combinational)
    logic [9:0] Y_out, Cb_out, Cr_out;

    always_comb begin
        // Y = (y_sum_reg >> 8), clip to 10-bit range
        case (y_sum_reg[15:8])
            8'd0:   Y_out = 10'd0;
            8'd1:   Y_out = 10'd1;
            8'd2:   Y_out = 10'd2;
            8'd3:   Y_out = 10'd3;
            8'd4:   Y_out = 10'd4;
            8'd5:   Y_out = 10'd5;
            8'd6:   Y_out = 10'd6;
            8'd7:   Y_out = 10'd7;
            8'd8:   Y_out = 10'd8;
            8'd9:   Y_out = 10'd9;
            8'd10:  Y_out = 10'd10;
            default: begin
                case (y_sum_reg[15:8] < 8'd255)
                    1'b1: Y_out = {2'b0, y_sum_reg[15:8]};
                    default: Y_out = 10'd255;
                endcase
            end
        endcase

        // Cb = (cb_sum_reg >> 8), clip to 10-bit range
        case (cb_sum_reg[15:8])
            8'd0:   Cb_out = 10'd0;
            default: begin
                case (cb_sum_reg[15:8] < 8'd255)
                    1'b1: Cb_out = {2'b0, cb_sum_reg[15:8]};
                    default: Cb_out = 10'd255;
                endcase
            end
        endcase

        // Cr = (cr_sum_reg >> 8), clip to 10-bit range
        case (cr_sum_reg[15:8])
            8'd0:   Cr_out = 10'd0;
            default: begin
                case (cr_sum_reg[15:8] < 8'd255)
                    1'b1: Cr_out = {2'b0, cr_sum_reg[15:8]};
                    default: Cr_out = 10'd255;
                endcase
            end
        endcase
    end

    // Block 7: Pixel Assembly
    always_comb begin
        ycbcr_pixel = {Y_out, Cb_out, Cr_out};
    end

    // Block 8: Video Timing Generator (720p @ 60Hz)
    // Horizontal: 1280 active, 110 front porch, 40 sync, 220 back porch (total 1650)
    // Vertical:   720 active, 5 front porch, 5 sync, 20 back porch (total 750)
    logic [10:0] h_counter;  // 0-1649
    logic [9:0]  v_counter;  // 0-749

    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                h_counter <= 11'd0;
                v_counter <= 10'd0;
            end
            1'b1: begin
                case (h_counter)
                    11'd1649: begin
                        h_counter <= 11'd0;
                        case (v_counter)
                            10'd749: v_counter <= 10'd0;
                            default: v_counter <= v_counter + 10'd1;
                        endcase
                    end
                    default: h_counter <= h_counter + 11'd1;
                endcase
            end
        endcase
    end

    // Block 9: Sync and Blanking Generation
    always_comb begin
        // Horizontal sync (40 pixels wide starting at 1380)
        case (h_counter)
            11'd1380, 11'd1381, 11'd1382, 11'd1383, 11'd1384, 11'd1385, 11'd1386, 11'd1387,
            11'd1388, 11'd1389, 11'd1390, 11'd1391, 11'd1392, 11'd1393, 11'd1394, 11'd1395,
            11'd1396, 11'd1397, 11'd1398, 11'd1399, 11'd1400, 11'd1401, 11'd1402, 11'd1403,
            11'd1404, 11'd1405, 11'd1406, 11'd1407, 11'd1408, 11'd1409, 11'd1410, 11'd1411,
            11'd1412, 11'd1413, 11'd1414, 11'd1415, 11'd1416, 11'd1417, 11'd1418, 11'd1419:
                h_sync = 10'b0;
            default: h_sync = 10'b1111111111;
        endcase

        // Vertical sync (5 lines starting at 725)
        case (v_counter)
            10'd725, 10'd726, 10'd727, 10'd728, 10'd729:
                v_sync = 10'b0;
            default: v_sync = 10'b1111111111;
        endcase

        // Horizontal blank (active pixels are 0-1279)
        case (h_counter < 11'd1280)
            1'b1: h_blank = 1'b0;
            default: h_blank = 1'b1;
        endcase

        // Vertical blank (active lines are 0-719)
        case (v_counter < 10'd720)
            1'b1: v_blank = 1'b0;
            default: v_blank = 1'b1;
        endcase
    end

endmodule,"module video_timing_generator (

//=============================================================================
// ATM Transaction Controller
//
// Industry Theme: Financial Transaction State Machine
// - Uses only 'case' and 'casez' statements (no if/else)
// - 4 procedural blocks: 2 always_ff (sequential), 2 always_comb (combinational)
// - Implements card insertion, PIN verification, withdrawal, and balance inquiry
//=============================================================================

module atm_controller (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Card interface
    input  logic card_inserted,
    input  logic [3:0] card_type,      // 4'b0001: debit, 4'b0010: credit, 4'b0100: prepaid

    // PIN pad interface
    input  logic [3:0] pin_entered,
    input  logic pin_enter_valid,

    // User selection (from touchscreen)
    input  logic [1:0] menu_select,    // 00: withdraw, 01: balance, 10: deposit, 11: exit

    // Amount entry
    input  logic [7:0] withdraw_amount,
    input  logic amount_valid,

    // Backend banking system interface
    input  logic [15:0] account_balance,
    input  logic pin_verified,
    input  logic transaction_approved,

    // Outputs
    output logic [7:0]  dispense_amount,
    output logic [15:0] new_balance,
    output logic [3:0]  transaction_status,  // 4-bit encoded status
    output logic        dispense_enable,
    output logic        card_eject,
    output logic        receipt_print
);

    //=========================================================================
    // State and Register Declarations
    //=========================================================================
    typedef enum logic [2:0] {
        IDLE,
        VERIFY_PIN,
        SELECT_TRANSACTION,
        PROCESS_WITHDRAWAL,
        PROCESS_BALANCE,
        COMPLETE,
        ERROR
    } state_t;

    state_t current_state, next_state;

    // Internal registers for transaction data
    logic [7:0]  pending_withdraw;
    logic [15:0] updated_balance;
    logic [3:0]  transaction_code;
    logic        card_valid;

    //=========================================================================
    // Block 1: Sequential State Register (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: current_state <= IDLE;
            1'b1: current_state <= next_state;
        endcase
    end

    //=========================================================================
    // Block 2: Combinational Next State Logic (always_comb with casez)
    //=========================================================================
    always_comb begin
        next_state = current_state;  // Default to current

        casez (current_state)
            IDLE: begin
                casez ({card_inserted, card_type})
                    5'b1_0001: next_state = VERIFY_PIN;  // Debit card
                    5'b1_0010: next_state = VERIFY_PIN;  // Credit card
                    5'b1_0100: next_state = ERROR;       // Prepaid card not accepted
                    5'b0_????: next_state = IDLE;
                    default:   next_state = ERROR;
                endcase
            end

            VERIFY_PIN: begin
                casez ({pin_enter_valid, pin_verified})
                    2'b11: next_state = SELECT_TRANSACTION;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = VERIFY_PIN;
                    default: next_state = ERROR;
                endcase
            end

            SELECT_TRANSACTION: begin
                casez (menu_select)
                    2'b00: next_state = PROCESS_WITHDRAWAL;
                    2'b01: next_state = PROCESS_BALANCE;
                    2'b10: next_state = ERROR;      // Deposit not supported in this ATM
                    2'b11: next_state = COMPLETE;
                    default: next_state = SELECT_TRANSACTION;
                endcase
            end

            PROCESS_WITHDRAWAL: begin
                casez ({amount_valid, transaction_approved})
                    2'b11: next_state = COMPLETE;
                    2'b10: next_state = ERROR;
                    2'b0?: next_state = PROCESS_WITHDRAWAL;
                    default: next_state = ERROR;
                endcase
            end

            PROCESS_BALANCE: begin
                casez (transaction_approved)
                    1'b1: next_state = COMPLETE;
                    1'b0: next_state = ERROR;
                    default: next_state = PROCESS_BALANCE;
                endcase
            end

            COMPLETE: begin
                casez (card_inserted)
                    1'b1: next_state = COMPLETE;  // Wait for card removal
                    1'b0: next_state = IDLE;
                    default: next_state = COMPLETE;
                endcase
            end

            ERROR: begin
                casez (card_inserted)
                    1'b1: next_state = ERROR;     // Wait for card removal in error state
                    1'b0: next_state = IDLE;
                    default: next_state = ERROR;
                endcase
            end

            default: next_state = IDLE;
        endcase
    end
    //=========================================================================
    // Block 3: Sequential Transaction Processing (always_ff with case)
    //=========================================================================
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                pending_withdraw <= 8'd0;
                updated_balance <= 16'd0;
                transaction_code <= 4'd0;
                card_valid <= 1'b0;
            end
            1'b1: begin
                case (current_state)
                    IDLE: begin
                        case (card_inserted)
                            1'b1: card_valid <= 1'b1;
                            1'b0: card_valid <= 1'b0;
                        endcase
                    end

                    VERIFY_PIN: begin
                        transaction_code <= 4'd1;  // PIN verification transaction
                    end

                    SELECT_TRANSACTION: begin
                        case (menu_select)
                            2'b00: transaction_code <= 4'd2;  // Withdrawal
                            2'b01: transaction_code <= 4'd3;  // Balance inquiry
                            2'b10: transaction_code <= 4'd4;  // Deposit (error case)
                            2'b11: transaction_code <= 4'd5;  // Exit
                        endcase
                    end

                    PROCESS_WITHDRAWAL: begin
                        case (amount_valid)
                            1'b1: pending_withdraw <= withdraw_amount;
                            default: ;
                        endcase

                        case (transaction_approved)
                            1'b1: updated_balance <= account_balance - pending_withdraw;
                            default: updated_balance <= account_balance;
                        endcase
                    end

                    PROCESS_BALANCE: begin
                        updated_balance <= account_balance;
                    end

                    COMPLETE: begin
                        case (menu_select)
                            2'b00: pending_withdraw <= 8'd0;  // Clear after completion
                            default: ;
                        endcase
                    end

                    ERROR: begin
                        transaction_code <= 4'd15;  // Error code
                        pending_withdraw <= 8'd0;
                    end
                endcase
            end
        endcase
    end

    //=========================================================================
    // Block 4: Combinational Output Logic (always_comb with case)
    //=========================================================================
    always_comb begin
        // Default assignments
        dispense_amount = 8'd0;
        new_balance = account_balance;
        transaction_status = 4'd0;
        dispense_enable = 1'b0;
        card_eject = 1'b0;
        receipt_print = 1'b0;

        case (current_state)
            IDLE: begin
                transaction_status = 4'd0;  // Ready
                card_eject = 1'b0;
            end

            VERIFY_PIN: begin
                transaction_status = 4'd1;  // Verifying
            end

            SELECT_TRANSACTION: begin
                transaction_status = 4'd2;  // Awaiting selection
            end

            PROCESS_WITHDRAWAL: begin
                case (transaction_approved)
                    1'b1: begin
                        transaction_status = 4'd3;  // Processing
                        dispense_amount = pending_withdraw;
                        new_balance = updated_balance;
                    end
                    default: transaction_status = 4'd4;  // Pending approval
                endcase
            end

            PROCESS_BALANCE: begin
                transaction_status = 4'd5;  // Retrieving balance
                new_balance = updated_balance;
            end

            COMPLETE: begin
                case (menu_select)
                    2'b00: begin  // Withdrawal completed
                        dispense_enable = 1'b1;
                        receipt_print = 1'b1;
                        transaction_status = 4'd6;  // Success - dispense
                        new_balance = updated_balance;
                    end
                    2'b01: begin  // Balance inquiry completed
                        receipt_print = 1'b1;
                        transaction_status = 4'd7;  // Success - balance shown
                        new_balance = updated_balance;
                    end
                    2'b11: begin  // Exit
                        card_eject = 1'b1;
                        transaction_status = 4'd8;  // Complete - card ejected
                    end
                    default: begin
                        transaction_status = 4'd9;  // Complete - other
                        card_eject = 1'b1;
                    end
                endcase
            end

            ERROR: begin
                case (transaction_code)
                    4'd1: transaction_status = 4'd10;  // PIN error
                    4'd2: transaction_status = 4'd11;  // Withdrawal error
                    4'd3: transaction_status = 4'd12;  // Balance error
                    4'd4: transaction_status = 4'd13;  // Deposit error
                    4'd15: transaction_status = 4'd14; // General error
                    default: transaction_status = 4'd15; // Unknown error
                endcase
                card_eject = 1'b1;
                dispense_amount = 8'd0;
            end
        endcase

        // Override for card removal during error or complete
        casez ({current_state, card_inserted})
            {ERROR, 1'b0}: card_eject = 1'b0;
            {COMPLETE, 1'b0}: card_eject = 1'b0;
            default: ;
        endcase
    end

endmodule,"module atm_controller_assertions (

module memory_controller #(
    parameter ADDR_WIDTH = 16,
    parameter DATA_WIDTH = 32,
    parameter ECC_WIDTH = 7,  // Hamming code for 32-bit data
    parameter NUM_MASTERS = 4
) (
    // Clock and reset
    input  logic clk,
    input  logic rst_n,

    // Master interfaces
    input  logic [NUM_MASTERS-1:0]        master_req,
    input  logic [NUM_MASTERS-1:0][ADDR_WIDTH-1:0] master_addr,
    input  logic [NUM_MASTERS-1:0]        master_rw,  // 1=write, 0=read
    input  logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_wdata,
    output logic [NUM_MASTERS-1:0]        master_grant,
    output logic [NUM_MASTERS-1:0][DATA_WIDTH-1:0] master_rdata,
    output logic [NUM_MASTERS-1:0]        master_ack,

    // Memory interface
    output logic                          mem_cs,
    output logic                          mem_we,
    output logic [ADDR_WIDTH-1:0]         mem_addr,
    output logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_wdata,
    input  logic [DATA_WIDTH+ECC_WIDTH-1:0] mem_rdata,
    input  logic                          mem_rdy
);

    // Internal state
    typedef enum logic [2:0] {
        IDLE         = 3'b000,
        ARB_WAIT     = 3'b001,
        CMD_SEND     = 3'b010,
        DATA_WAIT    = 3'b011,
        DATA_CAPTURE = 3'b100,
        ECC_CHECK    = 3'b101,
        RESPONSE     = 3'b110
    } state_t;

    state_t current_state, next_state;

    // Arbitration and request tracking
    logic [NUM_MASTERS-1:0] req_latched;
    logic [NUM_MASTERS-1:0] req_priority;
    logic [NUM_MASTERS-1:0] grant_current;
    logic [ADDR_WIDTH-1:0]  active_addr;
    logic                   active_rw;
    logic [DATA_WIDTH-1:0]  active_wdata;
    logic [NUM_MASTERS-1:0] active_master;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_encoded_data;
    logic [DATA_WIDTH+ECC_WIDTH-1:0] ecc_decoded_data;
    logic [ECC_WIDTH-1:0]   ecc_syndrome;
    logic                   ecc_error;
    logic                   ecc_corrected;

    // Counter for timing
    logic [2:0] wait_counter;
    logic [2:0] wait_target;

    // Pipeline registers
    logic [DATA_WIDTH-1:0] response_data;
    logic [NUM_MASTERS-1:0] response_master;
    logic response_valid;

    //------------------------------------------------------------------------
    // Block 1: Request Latching (Sequential)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: req_latched <= '0;
            1'b1: begin
                case (current_state)
                    IDLE: req_latched <= master_req;
                    CMD_SEND: begin
                        case (mem_rdy)
                            1'b1: req_latched <= req_latched & ~grant_current;
                            default: req_latched <= req_latched;
                        endcase
                    end
                    default: req_latched <= req_latched;
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 2: Priority Encoder (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        req_priority = 4'b0000;

        // Fixed priority: Master 0 > Master 1 > Master 2 > Master 3
        casez (req_latched)
            4'b???1: req_priority = 4'b0001;
            4'b??10: req_priority = 4'b0010;
            4'b?100: req_priority = 4'b0100;
            4'b1000: req_priority = 4'b1000;
            default: req_priority = 4'b0000;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 3: State Transition Logic (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        next_state = current_state;

        case (current_state)
            IDLE: begin
                case (|req_latched)
                    1'b1: next_state = ARB_WAIT;
                    default: next_state = IDLE;
                endcase
            end

            ARB_WAIT: begin
                case (req_priority != 4'b0000)
                    1'b1: next_state = CMD_SEND;
                    default: next_state = ARB_WAIT;
                endcase
            end

            CMD_SEND: begin
                case (mem_rdy)
                    1'b1: begin
                        case (active_rw)
                            1'b1: next_state = DATA_WAIT;
                            default: next_state = DATA_CAPTURE;
                        endcase
                    end
                    default: next_state = CMD_SEND;
                endcase
            end

            DATA_WAIT: begin
                case (wait_counter == wait_target)
                    1'b1: next_state = DATA_CAPTURE;
                    default: next_state = DATA_WAIT;
                endcase
            end

            DATA_CAPTURE: begin
                case (mem_rdy)
                    1'b1: begin
                        case (active_rw)
                            1'b1: next_state = RESPONSE;
                            default: next_state = ECC_CHECK;
                        endcase
                    end
                    default: next_state = DATA_CAPTURE;
                endcase
            end

            ECC_CHECK: begin
                next_state = RESPONSE;
            end

            RESPONSE: begin
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------------
    // Block 4: Main State Machine and Grant Logic (Sequential - Single Block)
    //------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: begin
                current_state <= IDLE;
                grant_current <= '0;
                active_master <= '0;
                active_addr <= '0;
                active_rw <= 1'b0;
                active_wdata <= '0;
                wait_counter <= 3'b0;
                wait_target <= 3'b0;
                response_data <= '0;
                response_master <= '0;
                response_valid <= 1'b0;
            end
            1'b1: begin
                current_state <= next_state;

                case (current_state)
                    IDLE: begin
                        grant_current <= '0;
                        response_valid <= 1'b0;
                        wait_counter <= 3'b0;
                    end

                    ARB_WAIT: begin
                        case (req_priority != 4'b0000)
                            1'b1: begin
                                grant_current <= req_priority;

                                // Capture active request details
                                case (req_priority)
                                    4'b0001: begin
                                        active_master <= 4'b0001;
                                        active_addr <= master_addr[0];
                                        active_rw <= master_rw[0];
                                        active_wdata <= master_wdata[0];
                                    end
                                    4'b0010: begin
                                        active_master <= 4'b0010;
                                        active_addr <= master_addr[1];
                                        active_rw <= master_rw[1];
                                        active_wdata <= master_wdata[1];
                                    end
                                    4'b0100: begin
                                        active_master <= 4'b0100;
                                        active_addr <= master_addr[2];
                                        active_rw <= master_rw[2];
                                        active_wdata <= master_wdata[2];
                                    end
                                    4'b1000: begin
                                        active_master <= 4'b1000;
                                        active_addr <= master_addr[3];
                                        active_rw <= master_rw[3];
                                        active_wdata <= master_wdata[3];
                                    end
                                    default: begin
                                        active_master <= active_master;
                                        active_addr <= active_addr;
                                        active_rw <= active_rw;
                                        active_wdata <= active_wdata;
                                    end
                                endcase
                            end
                            default: begin
                                grant_current <= grant_current;
                                active_master <= active_master;
                                active_addr <= active_addr;
                                active_rw <= active_rw;
                                active_wdata <= active_wdata;
                            end
                        endcase
                    end

                    CMD_SEND: begin
                        case (mem_rdy)
                            1'b1: begin
                                wait_counter <= 3'b0;
                                case (active_rw)
                                    1'b1: wait_target <= 3'd3;
                                    default: wait_target <= 3'd2;
                                endcase
                            end
                            default: begin
                                wait_counter <= wait_counter;
                                wait_target <= wait_target;
                            end
                        endcase
                    end

                    DATA_WAIT: begin
                        wait_counter <= wait_counter + 1'b1;
                    end

                    DATA_CAPTURE: begin
                        case (mem_rdy)
                            1'b1: begin
                                case (active_rw)
                                    1'b0: begin
                                        response_data <= ecc_decoded_data[DATA_WIDTH-1:0];
                                        response_master <= active_master;
                                        response_valid <= 1'b1;
                                    end
                                    default: begin
                                        response_data <= response_data;
                                        response_master <= response_master;
                                        response_valid <= response_valid;
                                    end
                                endcase
                            end
                            default: begin
                                response_data <= response_data;
                                response_master <= response_master;
                                response_valid <= response_valid;
                            end
                        endcase
                    end

                    RESPONSE: begin
                        // Hold values during response
                    end

                    default: begin
                        // Hold all values
                    end
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 5: ECC Encoding for Write Data (Sequential - Falling Edge)
    //------------------------------------------------------------------------
    always_ff @(negedge clk or negedge rst_n) begin
        case (rst_n)
            1'b0: ecc_encoded_data <= '0;
            1'b1: begin
                case (current_state)
                    CMD_SEND: begin
                        case (active_rw)
                            1'b1: begin
                                // Generate Hamming code for 32-bit data
                                ecc_encoded_data[DATA_WIDTH-1:0] <= active_wdata;
                                ecc_encoded_data[DATA_WIDTH +: ECC_WIDTH] <= {
                                    ^(active_wdata & 32'hAAAAAAAA),  // Even parity for bit0
                                    ^(active_wdata & 32'hCCCCCCCC),  // Even parity for bit1
                                    ^(active_wdata & 32'hF0F0F0F0),  // Even parity for bit2
                                    ^(active_wdata & 32'hFF00FF00),  // Even parity for bit3
                                    ^(active_wdata & 32'hFFFF0000),  // Even parity for bit4
                                    ^(active_wdata & 32'hFFFFFFFF),  // Overall parity
                                    ^(active_wdata & 32'hF0F0F0F0) ^ ^(active_wdata & 32'h0F0F0F0F)
                                };
                            end
                            default: ecc_encoded_data <= ecc_encoded_data;
                        endcase
                    end
                    default: ecc_encoded_data <= ecc_encoded_data;
                endcase
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 6: ECC Decoding and Error Detection (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        ecc_syndrome = '0;
        ecc_error = 1'b0;
        ecc_corrected = 1'b0;
        ecc_decoded_data = mem_rdata;

        // Calculate syndrome bits using case
        case (1'b1)
            1'b1: begin
                ecc_syndrome[0] = ^mem_rdata[31:0] ^ mem_rdata[32];
                ecc_syndrome[1] = ^(mem_rdata[31:0] & 32'hAAAAAAAA) ^ mem_rdata[33];
                ecc_syndrome[2] = ^(mem_rdata[31:0] & 32'hCCCCCCCC) ^ mem_rdata[34];
                ecc_syndrome[3] = ^(mem_rdata[31:0] & 32'hF0F0F0F0) ^ mem_rdata[35];
                ecc_syndrome[4] = ^(mem_rdata[31:0] & 32'hFF00FF00) ^ mem_rdata[36];
                ecc_syndrome[5] = ^(mem_rdata[31:0] & 32'hFFFF0000) ^ mem_rdata[37];
                ecc_syndrome[6] = ^mem_rdata ^ mem_rdata[38];
            end
        endcase

        // Error detection
        case (ecc_syndrome != 7'b0)
            1'b1: ecc_error = 1'b1;
            default: ecc_error = 1'b0;
        endcase

        // Error correction based on syndrome
        case (ecc_syndrome)
            7'b0000001: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[0] = ~mem_rdata[0];
            end
            7'b0000010: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[1] = ~mem_rdata[1];
            end
            7'b0000100: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[2] = ~mem_rdata[2];
            end
            7'b0001000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[3] = ~mem_rdata[3];
            end
            7'b0010000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[4] = ~mem_rdata[4];
            end
            7'b0100000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[5] = ~mem_rdata[5];
            end
            7'b1000000: begin
                ecc_corrected = 1'b1;
                ecc_decoded_data[6] = ~mem_rdata[6];
            end
            default: begin
                ecc_corrected = 1'b0;
                ecc_decoded_data = ecc_decoded_data;
            end
        endcase
    end

    //------------------------------------------------------------------------
    // Block 7: Output Assignments (Combinational - Case Only)
    //------------------------------------------------------------------------
    always_comb begin
        // Default assignments
        master_grant = 4'b0000;
        master_ack = 4'b0000;
        master_rdata = '{default: '0};
        mem_cs = 1'b0;
        mem_we = 1'b0;
        mem_addr = '0;
        mem_wdata = '0;

        case (current_state)
            ARB_WAIT: begin
                master_grant = req_priority;
            end

            CMD_SEND: begin
                case (mem_rdy)
                    1'b1: begin
                        mem_cs = 1'b1;
                        mem_we = active_rw;
                        mem_addr = active_addr;
                        case (active_rw)
                            1'b1: mem_wdata = ecc_encoded_data;
                            default: mem_wdata = '0;
                        endcase
                    end
                    default: begin
                        mem_cs = 1'b0;
                        mem_we = 1'b0;
                    end
                endcase
            end

            DATA_CAPTURE: begin
                case (mem_rdy)
                    1'b1: begin
                        mem_cs = 1'b1;
                        mem_we = active_rw;
                        mem_addr = active_addr;
                    end
                    default: begin
                        mem_cs = 1'b0;
                        mem_we = 1'b0;
                    end
                endcase
            end

            RESPONSE: begin
                case (response_master)
                    4'b0001: begin
                        master_rdata[0] = response_data;
                        master_ack = 4'b0001;
                    end
                    4'b0010: begin
                        master_rdata[1] = response_data;
                        master_ack = 4'b0010;
                    end
                    4'b0100: begin
                        master_rdata[2] = response_data;
                        master_ack = 4'b0100;
                    end
                    4'b1000: begin
                        master_rdata[3] = response_data;
                        master_ack = 4'b1000;
                    end
                    default: begin
                        master_rdata = '{default: '0};
                        master_ack = 4'b0000;
                    end
                endcase
            end

            default: begin
                master_grant = 4'b0000;
                master_ack = 4'b0000;
                master_rdata = '{default: '0};
                mem_cs = 1'b0;
                mem_we = 1'b0;
            end
        endcase
    end

endmodule,"module memory_controller_assertions #(

module fifo #(
    parameter DEPTH = 16,           // Number of entries
    parameter DATA_WIDTH = 8,       // Width of data
    parameter ALMOST_THRESHOLD = 4  // Almost full/empty margin
) (
    input logic clk,
    input logic rst_n,
    input logic wr_en,
    input logic rd_en,
    input logic [DATA_WIDTH-1:0] wr_data,
    output logic [DATA_WIDTH-1:0] rd_data,
    output logic full,
    output logic empty,
    output logic almost_full,
    output logic almost_empty
);

    // Local parameters for pointer widths
    localparam PTR_WIDTH = $clog2(DEPTH);
    localparam PTR_MAX   = DEPTH - 1;

    // ------------------------------------------------------------
    // 1. Sequential Block: Pointer Logic
    // ------------------------------------------------------------
    logic [PTR_WIDTH-1:0] wr_ptr, rd_ptr;
    logic [PTR_WIDTH-1:0] wr_ptr_next, rd_ptr_next;
    logic                  wr_ptr_en, rd_ptr_en;

    // Write pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, wr_ptr_en})
            2'b0?: wr_ptr <= '0;                    // Reset when rst_n is 0
            2'b11: wr_ptr <= wr_ptr_next;           // Enable when rst_n=1 and wr_ptr_en=1
            default: wr_ptr <= wr_ptr;              // Hold otherwise
        endcase
    end

    // Read pointer sequential logic
    always_ff @(posedge clk or negedge rst_n) begin
        case ({rst_n, rd_ptr_en})
            2'b0?: rd_ptr <= '0;                    // Reset when rst_n is 0
            2'b11: rd_ptr <= rd_ptr_next;           // Enable when rst_n=1 and rd_ptr_en=1
            default: rd_ptr <= rd_ptr;              // Hold otherwise
        endcase
    end

    // ------------------------------------------------------------
    // 2. Combinational Block: Status Calculation
    // ------------------------------------------------------------
    logic [PTR_WIDTH:0]  count;           // Current fill level (1 extra bit)
    logic [PTR_WIDTH-1:0] wr_ptr_comb, rd_ptr_comb;
    logic                 full_comb, empty_comb;
    logic                 almost_full_comb, almost_empty_comb;
    logic                 wr_enable, rd_enable;

    // Calculate current fill level using difference between pointers
    always_comb begin
        // Default assignments
        wr_ptr_comb = wr_ptr;
        rd_ptr_comb = rd_ptr;

        // Determine count based on pointer relationship
        case (1'b1)  // Using case for conditional logic
            (wr_ptr == rd_ptr): begin
                count = '0;
            end
            (wr_ptr > rd_ptr): begin
                // No wrap: count = wr_ptr - rd_ptr
                count = wr_ptr - rd_ptr;
            end
            (wr_ptr < rd_ptr): begin
                // Wrap occurred: count = (DEPTH - rd_ptr) + wr_ptr
                count = (PTR_MAX - rd_ptr) + wr_ptr + 1;
            end
            default: begin
                count = '0;
            end
        endcase
    end

    // Generate status flags using case statements
    always_comb begin
        // Empty flag
        case (count)
            0: empty_comb = 1'b1;
            default: empty_comb = 1'b0;
        endcase

        // Full flag
        case (count)
            DEPTH: full_comb = 1'b1;
            default: full_comb = 1'b0;
        endcase

        // Almost empty flag
        case (1'b1)
            ((count <= ALMOST_THRESHOLD) && (count != 0)): almost_empty_comb = 1'b1;
            default: almost_empty_comb = 1'b0;
        endcase

        // Almost full flag
        case (1'b1)
            ((count >= (DEPTH - ALMOST_THRESHOLD)) && (count != DEPTH)): almost_full_comb = 1'b1;
            default: almost_full_comb = 1'b0;
        endcase
    end

    // Generate enable signals with case statements
    always_comb begin
        // Write enable logic
        case ({wr_en, full_comb})
            2'b10: wr_enable = 1'b1;
            default: wr_enable = 1'b0;
        endcase

        // Read enable logic
        case ({rd_en, empty_comb})
            2'b10: rd_enable = 1'b1;
            default: rd_enable = 1'b0;
        endcase
    end

    // Assign pointer enables
    assign wr_ptr_en = wr_enable;
    assign rd_ptr_en = rd_enable;

    // Assign status outputs
    assign empty = empty_comb;
    assign full = full_comb;
    assign almost_empty = almost_empty_comb;
    assign almost_full = almost_full_comb;

    // ------------------------------------------------------------
    // 3. Combinational Block: Next Pointer Calculation
    // ------------------------------------------------------------
    always_comb begin
        // Default: stay at current value
        wr_ptr_next = wr_ptr;
        rd_ptr_next = rd_ptr;

        // Write pointer next state using case
        case (wr_ptr_en)
            1'b1: begin
                case (wr_ptr)
                    PTR_MAX: wr_ptr_next = '0;
                    default: wr_ptr_next = wr_ptr + 1;
                endcase
            end
            default: wr_ptr_next = wr_ptr;
        endcase

        // Read pointer next state using case
        case (rd_ptr_en)
            1'b1: begin
                case (rd_ptr)
                    PTR_MAX: rd_ptr_next = '0;
                    default: rd_ptr_next = rd_ptr + 1;
                endcase
            end
            default: rd_ptr_next = rd_ptr;
        endcase
    end

    // ------------------------------------------------------------
    // 4. Sequential Block: Memory Array
    // ------------------------------------------------------------
    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Write operation
    always_ff @(posedge clk) begin
        case (wr_enable)
            1'b1: mem[wr_ptr] <= wr_data;
            default: ;
        endcase
    end

    // ------------------------------------------------------------
    // 5. Output Logic: Read Data Mux
    // ------------------------------------------------------------
    // Combinational read with case to select output
    always_comb begin
        // Use case to select output based on read pointer
        case (rd_ptr)
            default: rd_data = mem[rd_ptr];
        endcase
    end

endmodule,"module fifo_assertions #(
